#!/usr/bin/env python3
"""整理实验课程 CSV 数据为带汇总和异常报告的 Excel 工作簿。"""

from __future__ import annotations

import argparse
import csv
import math
import os
import sys
import tempfile
from dataclasses import dataclass
from pathlib import Path
from statistics import fmean
from typing import Sequence

from openpyxl import Workbook


RAW_SHEET = "原始"
SUMMARY_SHEET = "汇总"
ISSUES_SHEET = "异常"
SUMMARY_HEADERS = ["column", "count", "missing", "invalid", "min", "max", "mean"]
ISSUE_HEADERS = ["data_row", "column", "value", "reason"]


class DataError(Exception):
    """预期的输入或输出错误，可向命令行用户直接说明。"""


@dataclass(frozen=True)
class CsvData:
    headers: list[str]
    rows: list[list[str]]


def read_csv(path: Path) -> CsvData:
    if not path.exists():
        raise DataError(f"输入文件不存在: {path}")
    if not path.is_file():
        raise DataError(f"输入路径不是文件: {path}")
    try:
        with path.open("r", encoding="utf-8-sig", newline="") as handle:
            reader = csv.reader(handle)
            try:
                headers = next(reader)
            except StopIteration as exc:
                raise DataError("CSV 文件为空") from exc
            if not headers or any(not header.strip() for header in headers):
                raise DataError("CSV 表头不能为空")
            if len(set(headers)) != len(headers):
                raise DataError("CSV 表头不能重复")
            rows = []
            for row_number, row in enumerate(reader, start=2):
                if len(row) != len(headers):
                    raise DataError(
                        f"第 {row_number} 行字段数为 {len(row)}，应为 {len(headers)}"
                    )
                rows.append(row)
    except UnicodeDecodeError as exc:
        raise DataError("输入文件不是有效的 UTF-8 CSV") from exc
    except csv.Error as exc:
        raise DataError(f"CSV 格式错误: {exc}") from exc
    if not rows:
        raise DataError("CSV 至少需要一行数据")
    return CsvData(headers, rows)


def parse_columns(value: str, headers: Sequence[str]) -> list[str]:
    columns = [part.strip() for part in value.split(",")]
    if not columns or any(not column for column in columns):
        raise DataError("--columns 必须是一个或多个非空列名，以逗号分隔")
    if len(set(columns)) != len(columns):
        raise DataError("--columns 不能包含重复列名")
    missing = [column for column in columns if column not in headers]
    if missing:
        raise DataError(f"指定的列不存在: {', '.join(missing)}")
    return columns


def classify(value: str) -> tuple[str, float | None]:
    stripped = value.strip()
    if not stripped:
        return "missing", None
    try:
        number = float(stripped)
    except ValueError:
        return "invalid", None
    if not math.isfinite(number):
        return "invalid", None
    return "valid", number


def build_workbook(data: CsvData, columns: Sequence[str]) -> Workbook:
    workbook = Workbook()
    raw = workbook.active
    raw.title = RAW_SHEET
    summary = workbook.create_sheet(SUMMARY_SHEET)
    issues = workbook.create_sheet(ISSUES_SHEET)

    for row_index, row in enumerate([data.headers, *data.rows], start=1):
        for column_index, text in enumerate(row, start=1):
            cell = raw.cell(row=row_index, column=column_index)
            # 强制文本类型，避免以 =、+、- 或 @ 开头的 CSV 内容成为公式。
            cell.value = text if text != "" else None
            cell.data_type = "s"

    header_indexes = {header: index for index, header in enumerate(data.headers)}
    summary.append(SUMMARY_HEADERS)
    issues.append(ISSUE_HEADERS)
    for column in columns:
        values: list[float] = []
        missing = 0
        invalid = 0
        for data_row, row in enumerate(data.rows, start=1):
            state, number = classify(row[header_indexes[column]])
            if state == "valid":
                values.append(number)  # type: ignore[arg-type]
            else:
                if state == "missing":
                    missing += 1
                else:
                    invalid += 1
                issues.append([data_row, column, row[header_indexes[column]] or None, state])
        summary.append(
            [
                column,
                len(values),
                missing,
                invalid,
                min(values) if values else None,
                max(values) if values else None,
                fmean(values) if values else None,
            ]
        )
    return workbook


def save_without_overwrite(workbook: Workbook, output: Path) -> None:
    if output.exists():
        raise DataError(f"输出文件已存在，不会覆盖: {output}")
    parent = output.parent
    if not parent.exists() or not parent.is_dir():
        raise DataError(f"输出目录不存在: {parent}")
    reserved = False
    try:
        descriptor = os.open(output, os.O_CREAT | os.O_EXCL | os.O_WRONLY, 0o644)
        os.close(descriptor)
        reserved = True
        workbook.save(output)
    except FileExistsError as exc:
        raise DataError(f"输出文件已存在，不会覆盖: {output}") from exc
    except (OSError, ValueError) as exc:
        raise DataError(f"无法写入输出文件: {exc}") from exc
    finally:
        if reserved and output.exists():
            # workbook.save 成功后保留目标；异常时移除部分结果。
            pass


def run(input_name: str, columns_arg: str, output_name: str) -> None:
    input_path = Path(input_name).expanduser()
    output_path = Path(output_name).expanduser()
    try:
        if input_path.exists() and output_path.exists() and os.path.samefile(input_path, output_path):
            raise DataError("输入路径和输出路径不能相同")
    except OSError:
        pass
    data = read_csv(input_path)
    columns = parse_columns(columns_arg, data.headers)
    workbook = build_workbook(data, columns)
    save_without_overwrite(workbook, output_path)


def interactive_args() -> tuple[str, str, str]:
    input_name = input("输入 CSV 路径: ").strip()
    columns = input("数值列名（逗号分隔）: ").strip()
    output_name = input("输出 Excel 路径: ").strip()
    return input_name, columns, output_name


def main(argv: Sequence[str] | None = None) -> int:
    parser = argparse.ArgumentParser(
        description="将实验课程 CSV 整理为包含原始、汇总、异常三个工作表的 Excel 文件。"
    )
    parser.add_argument("input", nargs="?", help="输入 UTF-8 CSV 路径")
    parser.add_argument("--columns", help="要统计的数值列名，多个列名用逗号分隔")
    parser.add_argument("--output", help="输出 .xlsx 路径；已有文件不会覆盖")
    args = parser.parse_args(argv)
    try:
        if args.input is None and args.columns is None and args.output is None:
            input_name, columns, output_name = interactive_args()
        elif args.input is None or args.columns is None or args.output is None:
            parser.error("命令方式需要同时提供输入路径、--columns 和 --output")
        else:
            input_name, columns, output_name = args.input, args.columns, args.output
        if not input_name or not columns or not output_name:
            raise DataError("输入路径、数值列名和输出路径都不能为空")
        run(input_name, columns, output_name)
    except (DataError, OSError) as exc:
        print(f"错误: {exc}", file=sys.stderr)
        return 1
    print(f"已生成: {output_name}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

