            else:
                if state == "missing":
                    missing += 1
                else:
                    invalid += 1
                issues.append([data_row, column, row[header_indexes[column]] or None, state])
        summary.append(
            [
                column,
                len(values),
                missing,
                invalid,
                min(values) if values else None,
                max(values) if values else None,
                fmean(values) if values else None,
            ]
        )
    return workbook


def save_without_overwrite(workbook: Workbook, output: Path) -> None:
    if output.exists():
        raise DataError(f"输出文件已存在，不会覆盖: {output}")
    parent = output.parent
    if not parent.exists() or not parent.is_dir():
        raise DataError(f"输出目录不存在: {parent}")
    reserved = False
    completed = False
    try:
        descriptor = os.open(output, os.O_CREAT | os.O_EXCL | os.O_WRONLY, 0o644)
        os.close(descriptor)
        reserved = True
        workbook.save(output)
        completed = True
    except FileExistsError as exc:
        raise DataError(f"输出文件已存在，不会覆盖: {output}") from exc
    except (OSError, ValueError) as exc:
        raise DataError(f"无法写入输出文件: {exc}") from exc
    finally:
        if reserved and not completed:
            try:
                output.unlink(missing_ok=True)
            except OSError:
                pass


def run(input_name: str, columns_arg: str, output_name: str) -> None:
    input_path = Path(input_name).expanduser()
    output_path = Path(output_name).expanduser()
    try:
        if input_path.exists() and output_path.exists() and os.path.samefile(input_path, output_path):
            raise DataError("输入路径和输出路径不能相同")
    except OSError:
        pass
    data = read_csv(input_path)
    columns = parse_columns(columns_arg, data.headers)
    workbook = build_workbook(data, columns)
    save_without_overwrite(workbook, output_path)


def interactive_args() -> tuple[str, str, str]:
    input_name = input("输入 CSV 路径: ").strip()
    columns = input("数值列名（逗号分隔）: ").strip()
    output_name = input("输出 Excel 路径: ").strip()
    return input_name, columns, output_name


def main(argv: Sequence[str] | None = None) -> int:
    parser = argparse.ArgumentParser(
        description="将实验课程 CSV 整理为包含原始、汇总、异常三个工作表的 Excel 文件。"
    )
    parser.add_argument("input", nargs="?", help="输入 UTF-8 CSV 路径")
    parser.add_argument("--columns", help="要统计的数值列名，多个列名用逗号分隔")
    parser.add_argument("--output", help="输出 .xlsx 路径；已有文件不会覆盖")
    args = parser.parse_args(argv)
    try:
        if args.input is None and args.columns is None and args.output is None:
            input_name, columns, output_name = interactive_args()
        elif args.input is None or args.columns is None or args.output is None:
            parser.error("命令方式需要同时提供输入路径、--columns 和 --output")
        else:
            input_name, columns, output_name = args.input, args.columns, args.output
        if not input_name or not columns or not output_name:
            raise DataError("输入路径、数值列名和输出路径都不能为空")
        run(input_name, columns, output_name)
    except (DataError, OSError) as exc:
        print(f"错误: {exc}", file=sys.stderr)
        return 1
    print(f"已生成: {output_name}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

